def copy_licenses(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    DatasetDistribution = apps.get_model("vitrina_resources", "DatasetDistribution")

    for dataset in Dataset.objects.all():
        if not dataset.licence:
            continue

        distributions = DatasetDistribution.objects.filter(dataset=dataset)

        if distributions.exists():
            distributions.update(licence=dataset.licence)


